import{_ as o,C as l,o as a,c as i,a2 as r,b as s,w as e,a as c,E,a3 as h}from"./chunks/framework.l6sz0Vgx.js";const _=JSON.parse('{"title":"铜与贵金属","description":"供给瓶颈与货币属性 — 铜看实体金看货币","frontmatter":{"title":"铜与贵金属","description":"供给瓶颈与货币属性 — 铜看实体金看货币"},"headers":[],"relativePath":"posts/econ-metals.md","filePath":"posts/econ-metals.md","lastUpdated":1791740552000}'),g={name:"posts/econ-metals.md"};function d(m,t,p,u,f,A){const n=l("Mermaid");return a(),i("div",null,[t[1]||(t[1]=r('<h1 id="铜与贵金属-供给瓶颈与货币属性" tabindex="-1">铜与贵金属：供给瓶颈与货币属性 <a class="header-anchor" href="#铜与贵金属-供给瓶颈与货币属性" aria-label="Permalink to &quot;铜与贵金属：供给瓶颈与货币属性&quot;">​</a></h1><blockquote><p><strong>用途：</strong> 行业分析第二篇，挂靠《股市笔记》§1（周期与信用）与《交易流派》大宗商品逻辑。不提供个股推荐，不构成投资建议。 <strong>证据标准：</strong> 每个数字须有<strong>日期 + 口径 + 来源</strong>；凡标&quot;<strong>待核</strong>&quot;未经逐条回溯原文，引用前须复核。</p></blockquote><h2 id="运行层-矿端锁死供给-新旧需求切换" tabindex="-1">运行层：矿端锁死供给，新旧需求切换 <a class="header-anchor" href="#运行层-矿端锁死供给-新旧需求切换" aria-label="Permalink to &quot;运行层：矿端锁死供给，新旧需求切换&quot;">​</a></h2><ul><li><strong>供给：</strong> 2026年全球铜精矿增量约13.5万吨、增速0.58%五年最低；原生精炼铜仅增5.2万吨，再生铜增26.5万吨对冲；精炼铜产量增速约1.11%（新浪四季报2026-09-22，转引期货研报）。老矿品位下滑、新矿7–10年周期、前期capex不足是长期项；智利/秘鲁（水/罢工/审批）、非洲（电力/灾害）是短期项。</li><li><strong>需求切换：</strong> 传统（地产/家电）拖累放缓；算力（摩根大通：AI数据中心2026年新增约47.5万吨，CME 2026-01-24转引）、储能电网托底；2024年全球数据中心用铜41.7万吨，2030年或至119.7万吨（国盛2026-01-01，转引）。</li><li><strong>平衡：</strong> 2025年过剩46.9万吨 → 2026年约25万吨 → 2027年约39.5万吨（弱过剩，新浪2026-09-22转引）；国际铜研究组织口径2026年缺口约15万吨（CME 2026-01-24转引）。口径不同结论同向：从宽松走向紧平衡。</li><li><strong>价格：</strong> LME铜2026-09-10盘中14,875美元/吨历史新高，沪铜9-08收110,620元/吨（新浪2026-09-22）。机构目标：汇丰13180、花旗12000、中邮13000美元/吨（CME 2026-01-24转引，仅记录分歧）。</li><li><strong>政策变量：</strong> 美国232铜关税：半成品已征50%，精炼铜拟2027年征15%、2028年30%（白宫/商务部公告，新浪2026-09-22转引）；贸易商提前囤美，美国消费占全球7%却囤62%–70%交易所库存（CME 2026-01-24转引），亚洲欧洲更紧。</li></ul>',4)),(a(),s(h,null,{default:e(()=>[E(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22%E7%9F%BF%E7%AB%AF%E7%93%B6%E9%A2%88%3Cbr%2F%3E%E5%93%81%E4%BD%8D%E5%8A%A0%E6%89%B0%E5%8A%A8%22%5D%20--%3E%20B%5B%22%E7%B2%BE%E7%82%BC%E7%BA%A6%E6%9D%9F%3Cbr%2F%3ETC%E4%BD%8E%E4%BD%8D%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E5%BA%93%E5%AD%98%E8%BD%AC%E7%A7%BB%3Cbr%2F%3E%E5%9B%A4%E7%BE%8E%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E4%BB%B7%E6%A0%BC%E4%B8%AD%E6%9E%A2%3Cbr%2F%3E%E4%B8%8A%E7%A7%BB%22%5D%0A%20%20%20%20D%20-.%20%22%E5%A4%8D%E4%BA%A7%E8%B6%85%E9%A2%84%E6%9C%9F%22%20.-%3E%20E%5B%22%E8%AF%81%E4%BC%AA%3Cbr%2F%3E%E8%BF%87%E5%89%A9%E5%9B%9E%E6%91%86%22%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[c(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r('<h2 id="定价层-铜看实体-金看货币" tabindex="-1">定价层：铜看实体，金看货币 <a class="header-anchor" href="#定价层-铜看实体-金看货币" aria-label="Permalink to &quot;定价层：铜看实体，金看货币&quot;">​</a></h2><ul><li><strong>铜（工业锚）：</strong> 定价锚定实体供需与产业周期，金融属性弱；COMEX-LME溢价、人民币汇率是本土观测锚（crainternational 2026-05-29）。</li><li><strong>金（货币锚）：</strong> 央行连续增持（中国央行连12个月，累计41吨，新浪/国信2026-11转引口径）+ ETF流入（2025年内净流入674吨，持有3893吨，东兴2026-12转引）+ 避险溢价；瑞银Teves：上半年或冲5000美元/盎司，下半年随宽松退出动能减弱（证券时报2026-01-21转引）。</li><li><strong>银（双属性）：</strong> 工业（光伏/电子）+ 金融；金银比仍在70上（国盛2026-01-01，转引），相对低估还是补涨看工业兑现；供需缺口或扩至6000吨级（东兴2026-12-16转引）。</li><li><strong>铜金比价：</strong> 本质是工业周期与避险的博弈，人民币企稳+利率企稳是底部拐点信号（crainternational 2026-05-29）；系统性风险到来时联动失效。</li></ul><h2 id="结构层-谁卡脖子" tabindex="-1">结构层：谁卡脖子 <a class="header-anchor" href="#结构层-谁卡脖子" aria-label="Permalink to &quot;结构层：谁卡脖子&quot;">​</a></h2><ul><li><strong>矿端：</strong> 7–10年周期 + 品位下滑 + 勘探capex不足，供给弹性长期弱；TC长期低位甚至负值，冶炼靠再生铜与高价传导活着。</li><li><strong>库存结构：</strong> 美国91.2天历史最高 vs 非美7.4天（9年15%分位，国盛2026-01-01转引）——总量过剩、结构短缺，脆弱平衡。</li><li><strong>黄金供需：</strong> 矿金低增长 + 央行年购超1000吨三年 + ETF回流，底部中枢上移、弹性看利率（东兴2026-12-16转引）。</li><li><strong>宏观压制：</strong> 美联储9-16加息至3.75%–4.00%、多数票委预期年内再加一次（新浪2026-09-22）；高利率压远期估值，是涨幅天花板而非趋势反转。</li></ul><h2 id="证伪层" tabindex="-1">证伪层 <a class="header-anchor" href="#证伪层" aria-label="Permalink to &quot;证伪层&quot;">​</a></h2><ul><li><strong>供给证伪：</strong> Grasberg/Panama全面复产、TC回升、再生铜超预期释放。</li><li><strong>需求证伪：</strong> AI capex/光伏/新能源车不及预期、地产链继续下行。</li><li><strong>货币证伪：</strong> 降息重启（金银的交易反转）、地缘缓和（避险溢价消退）。</li><li><strong>跟踪项：</strong> 精矿TC、COMEX-LME溢价、非美库存天数、央行购金月度、232细则落地节奏。</li></ul><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>新浪铜四季报（2026-09-22）：<a href="https://finance.sina.com.cn/money/future/2026-09-22/doc-inissuic8928545.shtml" target="_blank" rel="noreferrer">https://finance.sina.com.cn/money/future/2026-09-22/doc-inissuic8928545.shtml</a></li><li>CME铂金铜双重变奏（2026-01-24）：<a href="https://www.cmegroup.com/cn-s/insights/media-partners/7he/2026-01-23.html" target="_blank" rel="noreferrer">https://www.cmegroup.com/cn-s/insights/media-partners/7he/2026-01-23.html</a></li><li>铜金比价（2026-05-29）：<a href="https://crainternational.com.cn/infor/view?id=105235" target="_blank" rel="noreferrer">https://crainternational.com.cn/infor/view?id=105235</a></li><li>瑞银Teves专访（2026-01-21）：<a href="https://www.stcn.com/article/detail/3603006.html" target="_blank" rel="noreferrer">https://www.stcn.com/article/detail/3603006.html</a></li><li>国盛有色年度策略（2026-01-01）：<a href="https://m.hibor.com.cn/wap_detail.aspx?id=049640cfaf6f531bb8186495361f4a8a" target="_blank" rel="noreferrer">https://m.hibor.com.cn/wap_detail.aspx?id=049640cfaf6f531bb8186495361f4a8a</a></li></ul>',8))])}const b=o(g,[["render",d]]);export{_ as __pageData,b as default};
